package calc;

/** Signals that an expression could not be evaluated (syntax error, division by zero or overflow). */
final class EvaluationException extends Exception {
    private static final long serialVersionUID = 1L;

    EvaluationException(String message) {
        super(message, null, false, false);
    }
}

package calc;

/**
 * Recursive-descent evaluator for 64-bit signed integer expressions.
 *
 * <pre>
 * expr    := term    (('+' | '-') term)*
 * term    := unary   (('*' | '/' | '%') unary)*
 * unary   := '-' unary | primary
 * primary := NUMBER | '(' expr ')'
 * </pre>
 *
 * The input is a single line as ASCII bytes; spaces and tabs may separate tokens.
 * Instances are single-use and not thread-safe.
 */
final class Evaluator {
    private final byte[] src;
    private final int end;
    private int pos;

    private Evaluator(byte[] src, int start, int end) {
        this.src = src;
        this.pos = start;
        this.end = end;
    }

    /** Evaluates {@code src[start, end)} as a complete expression. */
    static long evaluate(byte[] src, int start, int end) throws EvaluationException {
        Evaluator evaluator = new Evaluator(src, start, end);
        long value = evaluator.expr();
        if (evaluator.peek() != -1) {
            throw new EvaluationException("unexpected trailing input");
        }
        return value;
    }

    private long expr() throws EvaluationException {
        long value = term();
        while (true) {
                int c = peek();
            if (c == '+') {
                pos++;
                value = apply('+', value, term());
            } else if (c == '-') {
                pos++;
                value = apply('-', value, term());
            } else {
                return value;
            }
        }
    }

    private long term() throws EvaluationException {
        long value = unary();
        while (true) {
            int c = peek();
            if (c == '*' || c == '/' || c == '%') {
                pos++;
                value = apply((char) c, value, unary());
            } else {
                return value;
            }
        }
    }

    private long unary() throws EvaluationException {
        // Iterate over runs of '-' rather than recursing, so long chains cannot exhaust the stack.
        int negations = 0;
        while (peek() == '-') {
            pos++;
            negations++;
        }
        long value = primary();
        for (int i = 0; i < negations; i++) {
            if (value == Long.MIN_VALUE) {
                throw new EvaluationException("overflow");
            }
            value = -value;
        }
        return value;
    }

    private long primary() throws EvaluationException {
        int c = peek();
        if (c == '(') {
            pos++;
            long value = expr();
            if (peek() != ')') {
                throw new EvaluationException("expected ')'");
            }
            pos++;
            return value;
        }
        if (isDigit(c)) {
            return number();
        }
        throw new EvaluationException("expected operand");
    }

    private long number() throws EvaluationException {
        long value = 0;
        boolean overflow = false;
        while (pos < end && isDigit(src[pos])) {
            int digit = src[pos++] - '0';
            if (value > (Long.MAX_VALUE - digit) / 10) {
                overflow = true;
            } else {
                value = value * 10 + digit;
            }
        }
        if (overflow) {
            throw new EvaluationException("literal out of range");
        }
        return value;
    }

    private static long apply(char op, long left, long right) throws EvaluationException {
        try {
            return switch (op) {
                case '+' -> Math.addExact(left, right);
                case '-' -> Math.subtractExact(left, right);
                case '*' -> Math.multiplyExact(left, right);
                case '/' -> {
                    requireNonZero(right);
                    yield Math.divideExact(left, right);
                }
                case '%' -> {
                    requireNonZero(right);
                    yield left % right;
                }
                default -> throw new IllegalArgumentException("unknown operator " + op);
            };
        } catch (ArithmeticException e) {
            throw new EvaluationException("overflow");
        }
    }

    private static void requireNonZero(long divisor) throws EvaluationException {
        if (divisor == 0) {
            throw new EvaluationException("division by zero");
        }
    }

    /** Skips blanks and returns the next byte without consuming it, or -1 at end of input. */
    private int peek() {
        while (pos < end && isBlank(src[pos])) {
            pos++;
        }
        return pos < end ? src[pos] : -1;
    }

    static boolean isBlank(int c) {
        return c == ' ' || c == '\t';
    }

    private static boolean isDigit(int c) {
        return c >= '0' && c <= '9';
    }
}

package calc;

import java.io.BufferedOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintStream;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;

/** Reads one expression per line from standard input and prints its value or {@code error}. */
public final class Main {
    /** Deeply nested parentheses recurse; run on a thread with a generous stack. */
    private static final long STACK_SIZE = 1L << 30;
    private static final byte[] ERROR = "error\n".getBytes(StandardCharsets.US_ASCII);

    private Main() {
    }

    public static void main(String[] args) throws Exception {
        Throwable[] failure = new Throwable[1];
        Thread worker = new Thread(null, () -> {
            try {
                run(System.in, System.out);
            } catch (Throwable t) {
                failure[0] = t;
            }
        }, "calc", STACK_SIZE);
        worker.start();
        worker.join();
        if (failure[0] != null) {
            failure[0].printStackTrace();
            System.exit(1);
        }
    }

    static void run(InputStream in, PrintStream stdout) throws IOException {
        OutputStream out = new BufferedOutputStream(stdout, 1 << 16);
        LineReader reader = new LineReader(in);
        byte[] line;
        while ((line = reader.next()) != null) {
            int length = reader.length();
            if (isBlank(line, length)) {
                continue;
            }
            byte[] result;
            try {
                result = (Evaluator.evaluate(line, 0, length) + "\n").getBytes(StandardCharsets.US_ASCII);
            } catch (EvaluationException | StackOverflowError e) {
                result = ERROR;
            }
            out.write(result);
        }
        out.flush();
    }

    private static boolean isBlank(byte[] line, int length) {
        for (int i = 0; i < length; i++) {
            if (!Evaluator.isBlank(line[i])) {
                return false;
            }
        }
        return true;
    }

    /** Minimal buffered reader that splits a byte stream on {@code '\n'}, reusing one line buffer. */
    private static final class LineReader {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int bufferPos;
        private int bufferLimit;
        private byte[] line = new byte[256];
        private int lineLength;

        LineReader(InputStream in) {
            this.in = in;
        }

        /** Returns the buffer holding the next line (see {@link #length()}), or null at end of input. */
        byte[] next() throws IOException {
            lineLength = 0;
            boolean sawAny = false;
            while (true) {
                if (bufferPos == bufferLimit) {
                    bufferLimit = in.read(buffer);
                    bufferPos = 0;
                    if (bufferLimit <= 0) {
                        bufferLimit = 0;
                        return sawAny ? line : null;
                    }
                }
                sawAny = true;
                int start = bufferPos;
                while (bufferPos < bufferLimit && buffer[bufferPos] != '\n') {
                    bufferPos++;
                }
                append(start, bufferPos);
                if (bufferPos < bufferLimit) {
                    bufferPos++; // consume '\n'
                    return line;
                }
            }
        }

        int length() {
            return lineLength;
        }

        private void append(int from, int to) {
            int count = to - from;
            if (lineLength + count > line.length) {
                line = Arrays.copyOf(line, Math.max(line.length * 2, lineLength + count));
            }
            System.arraycopy(buffer, from, line, lineLength, count);
            lineLength += count;
        }
    }
}
